175:         public void EnsureThumbnail()
176:         {
177:             if (Thumbnail != null) return;
178:             if (_thumbnailState == ThumbnailState.Loading) return;   // 进行中不重复触发（防抖动）
179: 
180:             // Pending / Failed → 触发解码；取消上一次仍在进行的解码（如有残留）
181:             _thumbnailCts?.Cancel();
182:             _thumbnailCts?.Dispose();
183:             _thumbnailCts = new System.Threading.CancellationTokenSource();
184:             var token = _thumbnailCts.Token;
185: 
186:             ThumbnailState = ThumbnailState.Loading;
187: 
188:             var path = FilePath;
189:             var dispatcher = System.Windows.Application.Current?.Dispatcher;
190:             if (dispatcher == null) return;
191: 
192:             System.Threading.Tasks.Task.Run(() =>
193:             {
194:                 if (token.IsCancellationRequested) return;
195:                 var thumbnail = ImagePreviewControl.LoadThumbnail(path, token);
196:                 if (token.IsCancellationRequested) return;
197:                 dispatcher.InvokeAsync(() =>
198:                 {
199:                     // 若已滚动离开（被取消），丢弃结果
200:                     if (token.IsCancellationRequested) return;
201:                     if (thumbnail != null)
202:                     {
203:                         Thumbnail = thumbnail;
204:                         ThumbnailState = ThumbnailState.Loaded;
205:                     }
206:                     else
207:                     {
208:                         // 解码失败：标记 Failed 显示占位。滚动离开再回来时 OnItemLoaded 会重新触发解码（rule-015 失败可见+可重试）
209:                         ThumbnailState = ThumbnailState.Failed;
210:                     }
211:                 });
212:             });
213:         }
