460:         // 全分辨率图像缓存（LRU，上限 30）——保留，供 ImageInfo.FullImage 懒加载
461:         private static readonly ImageCache s_fullImageCache = new ImageCache(maxCacheSize: 30);
462: 
463:         // 缩略图缓存（LRU，上限 50）——跨实例共享，滚动复用不重复解码
464:         private static readonly ImageCache s_thumbnailCache = new ImageCache(maxCacheSize: 50);
465:         private static readonly object s_thumbnailLock = new object();
466: 
467:         /// <summary>
468:         /// 全局缩略图并发上限：clamp(CPU-1, 4, 16)。
469:         /// 对齐 ImageGlass Photo.cs:66-67，避免海量缩略图无限并发挤爆线程池（rule-008 治本）。
470:         /// </summary>
471:         private static readonly int s_thumbnailConcurrency =
472:             Math.Clamp(Environment.ProcessorCount - 1, 4, 16);
473:         private static readonly SemaphoreSlim s_thumbnailThrottle =
474:             new(s_thumbnailConcurrency, s_thumbnailConcurrency);
475: 
476:         /// <summary>
477:         /// 缩略图加载：后台线程 WIC 解码 + DecodePixelWidth 缩小 + Freeze。
478:         /// 对齐成熟方案（ImageGlass/微软官方）：
479:         /// - 并发节流：全局信号量 clamp(CPU-1,4,16)，避免线程池饱和也不串行（对齐 ImageGlass Photo.cs:66-67）
480:         /// - 锁只保护缓存字典（微秒级短临界区），解码在锁外并行（已治本）
481:         /// - 解码失败直接返回 null + WARN 日志（rule-015 失败可见），不做无效降级——
482:         ///   实测 System.Drawing 兜底转 PNG 后仍走 BitmapImage(WIC)，救不回 WIC 解不了的格式
483:         ///   （对齐 ImageGlass 的容错仅靠其真正多引擎，本项目 Win11 标准格式 WIC 全覆盖，无需兜底）
484:         /// </summary>
485:         internal static BitmapImage? LoadThumbnail(string filePath, System.Threading.CancellationToken token = default)
486:         {
487:             if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
488:                 return null;
489: 
490:             // 快路径：锁内只查缓存（微秒级），命中直接返回
491:             lock (s_thumbnailLock)
492:             {
493:                 var cached = s_thumbnailCache.Get(filePath);
494:                 if (cached != null) return cached as BitmapImage;
495:             }
496: 
497:             // 节流进入：最多 clamp(CPU-1,4,16) 个并发解码，避免线程池饱和
498:             BitmapImage? bitmap = null;
499:             try
500:             {
501:                 s_thumbnailThrottle.Wait(token);
502:             }
503:             catch (System.OperationCanceledException)
504:             {
505:                 // 滚动离开被取消：不降级、不报错，直接丢弃（对齐 ImageGlass 不可见即取消）
506:                 return null;
507:             }
508:             try
509:             {
510:                 // 慢路径：锁外并行解码（I/O + CPU，互不阻塞）
511:                 try
512:                 {
513:                     bitmap = DecodeThumbnailCore(filePath);   // WIC
514:                 }
515:                 catch (Exception ex)   // WIC 解不了（NotSupportedException / COM 异常等）
516:                 {
517:                     // rule-015：失败可见，禁止静默吞异常；不做无效降级
518:                     VisionLogger.Instance.Log(LogLevel.Warning,
519:                         $"缩略图解码失败 | {filePath} | {ex.GetType().Name}: {ex.Message}",
520:                         "ImagePreviewControl");
521:                 }
522:             }
523:             finally
524:             {
525:                 s_thumbnailThrottle.Release();
526:             }
527: 
528:             if (bitmap == null) return null;
529: 
530:             // 写缓存：锁内极短
531:             lock (s_thumbnailLock)
532:             {
533:                 s_thumbnailCache.Set(filePath, bitmap);
534:             }
535:             return bitmap;
536:         }
