553:         /// <summary>
554:         /// 全分辨率图像加载（简化版）：ImageInfo.FullImage 懒加载入口。
555:         /// 用 UriSource + OnLoad 内建解码，替代原自研解码器/CleanupScheduler 链路。
556:         /// </summary>
557:         public static BitmapImage? LoadImageOptimized(string filePath)
558:         {
559:             if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
560:                 return null;
561: 
562:             // 全图懒加载在主 UI 线程触发，无并发竞争；查缓存命中直接返回，未命中解码后写入
563:             var cached = s_fullImageCache.Get(filePath);
564:             if (cached != null) return cached as BitmapImage;
565: 
566:             try
567:             {
568:                 var bitmap = new BitmapImage();
569:                 bitmap.BeginInit();
570:                 bitmap.UriSource = new Uri(filePath, UriKind.RelativeOrAbsolute);
571:                 bitmap.CacheOption = BitmapCacheOption.OnLoad;
572:                 bitmap.EndInit();
573:                 bitmap.Freeze();
574:                 s_fullImageCache.Set(filePath, bitmap);
575:                 return bitmap;

