1995:         /// <param name="solution">已加载的解决方案（含主工作流与子程序工作流）</param>
1996:         private void PreCompileScriptNodes(Solution solution)
1997:         {
1998:             if (solution?.Workflows == null)
1999:             {
2000:                 return;
2001:             }
2002: 
2003:             var allNodes = solution.Workflows.SelectMany(w => w.Nodes).ToList();
2004:             _logger?.LogInfo($"[预编译] 遍历到节点总数={allNodes.Count}, Workflows={solution.Workflows.Count}", nameof(MainWindowViewModel));
2005:             foreach (var n in allNodes)
2006:             {
2007:                 var tool = ToolRegistry.CreateToolInstance(n.ToolType);
2008:                 _logger?.LogInfo(
2009:                     $"[预编译] 节点=[{n.Name}] ToolType=[{n.ToolType}] ParamsType=[{n.Parameters?.GetType().Name ?? "null"}] Tool=[{tool?.GetType().Name ?? "null"}] IsPrecompilable=[{tool is IPrecompilableTool}]",
2010:                     nameof(MainWindowViewModel));
2011:             }
2012: 
2013:             var precompilableNodes = allNodes
2014:                 .Where(n => n.Parameters != null)
2015:                 .Select(n => new
2016:                 {
2017:                     Node = n,
2018:                     Tool = ToolRegistry.CreateToolInstance(n.ToolType)
2019:                 })
2020:                 .Where(x => x.Tool is IPrecompilableTool && x.Node.Parameters != null)
2021:                 .ToList();
2022: 
2023:             _logger?.LogInfo($"[预编译] 可预编译节点数={precompilableNodes.Count}", nameof(MainWindowViewModel));
2024: 
2025:             if (precompilableNodes.Count == 0)
2026:             {
2027:                 _logger?.LogInfo("[预编译] 无可预编译节点，跳过", nameof(MainWindowViewModel));
2028:                 return;
2029:             }
2030: 
2031:             var sw = System.Diagnostics.Stopwatch.StartNew();
2032: 
2033:             _logger?.LogInfo($"[预编译] 开始预编译, 节点数={precompilableNodes.Count}", nameof(MainWindowViewModel));
2034: 
2035:             // 后台 Task 并行预编译：
2036:             // - 并行任务在线程池执行（无 UI 同步上下文），避免在 UI 线程直接调 Parallel.ForEach 的调度死锁
2037:             // - 多脚本并行，启动时间不随脚本数成倍增加
2038:             // - UI 线程同步等待完成（主窗口 Show 前预编译结束，确保所见即所得：打开工作区后脚本已编译）
2039:             var parallelOptions = new ParallelOptions
2040:             {
2041:                 MaxDegreeOfParallelism = Math.Max(1, Environment.ProcessorCount / 2)
2042:             };
2043: 
2044:             var snapshot = precompilableNodes.ToList();
2045:             System.Threading.Tasks.Task.Run(() =>
2046:             {
2047:                 Parallel.ForEach(snapshot, parallelOptions, x =>
2048:                 {
2049:                     try
2050:                     {
2051:                         var tool = (IPrecompilableTool)x.Tool!;
2052:                         var errors = tool.PreCompile(x.Node.Parameters!);
2053:                         _logger?.LogInfo(
2054:                             $"[预编译] 节点=[{x.Node.Name}] 预编译完成, 诊断数={errors.Count}" + (errors.Count > 0 ? $", 诊断=[{string.Join("; ", errors.Take(2))}]" : ""),
2055:                             nameof(MainWindowViewModel));
2056:                     }
2057:                     catch (Exception ex)
2058:                     {
2059:                         _logger?.LogError($"[预编译] 节点=[{x.Node.Name}] 预编译异常: {ex.Message}", nameof(MainWindowViewModel));
2060:                     }
2061:                 });
2062:             }).GetAwaiter().GetResult();
2063: 
2064:             sw.Stop();
2065:             LogSuccess($"预编译完成: {precompilableNodes.Count} 个节点, 耗时 {sw.ElapsedMilliseconds}ms");

55:         public static void RegisterTool(Type toolType)
56:         {
57:             if (toolType == null)
58:                 throw new ArgumentNullException(nameof(toolType));
59: 
60:             var attr = toolType.GetCustomAttribute<ToolAttribute>();
61:             if (attr == null)
62:                 throw new ArgumentException($"类型 {toolType.Name} 缺少 [Tool] 特性");
63: 
64:             lock (_lock)
65:             {
66:                 _toolTypes[attr.Id] = toolType;
67:                 
68:                 // 提取参数类型信息（用于诊断）
69:                 Type? paramsType = null;
70:                 foreach (var iface in toolType.GetInterfaces())
71:                 {
72:                     if (iface.IsGenericType && iface.GetGenericTypeDefinition() == typeof(IToolPlugin<,>))
73:                     {
74:                         var genericArgs = iface.GetGenericArguments();
75:                         if (genericArgs.Length >= 2)
76:                         {
77:                             paramsType = genericArgs[0];
78:                             break;
79:                         }
80:                     }
81:                 }
82:                 
83:                 // 主动注册参数类型到多态序列化配置
84:                 if (paramsType != null && typeof(ToolParameters).IsAssignableFrom(paramsType))
85:                 {
86:                     RegisterParameterTypeToRegistry(paramsType);
87:                 }
88:                 
89:                 // ✅ 基于输出变量契约（IToolPlugin.OutputVariables）提取并缓存属性元数据
90:                 var pluginInstance = CreateToolInstance(attr.Id);
91:                 if (pluginInstance != null)
92:                     ExtractPropertyMetadata(attr.Id, pluginInstance);
93:                 
94:                 VisionLogger.Instance.Log(LogLevel.Success,
95:                     $"工具注册成功: {attr.DisplayName} (Id={attr.Id}, ParamsType={paramsType?.Name ?? "未指定"})",
96:                     "ToolRegistry");
97:             }
98:         }
