1092:     public void RebuildWorkspace(bool refreshReferences = false)
1093:     {
1094:         if (_getReferences == null)
1095:             throw new InvalidOperationException("未注入引用来源：请先调用 SetReferenceProvider（rule-008 报错优先）。");
1096:         if (_getGeneratedCode == null || _getUserCode == null)
1097:             throw new InvalidOperationException("未注入代码来源：请先调用 SetCodeSource（rule-008 报错优先）。");
1098: 
1099:         // 实例级复用：workspace 已建且非强制刷新引用 → 只更新 generated 文档文本（user 文档由增量容器自动同步）
1100:         if (_workspaceInitialized && !refreshReferences)
1101:         {
1102:             var genCode = _getGeneratedCode();
1103:             _workspace!.SetCurrentSolution(_workspace.CurrentSolution
1104:                 .WithDocumentText(_documentId!, SourceText.From(genCode)));
1105:             return;
1106:         }
1107: 
1108:         var generatedCode = _getGeneratedCode();
1109:         var userCode = _getUserCode();
1110:         var totalSw = System.Diagnostics.Stopwatch.StartNew();
1111: 
1112:         PluginLogger.Info($"[补全] RebuildWorkspace 开始: generatedCodeLen={generatedCode.Length}, userCodeLen={userCode.Length}", typeName);
1113: 
1114:         _workspace?.Dispose();
1115: 
1116:         // 加载 MefHostServices 确保所有 CompletionProvider 可用（缓存机制，首次慢后续快）
1117:         var sw = System.Diagnostics.Stopwatch.StartNew();
1118:         var host = GetSharedMefHost();
1119:         PluginLogger.Info($"[补全] MefHostServices 创建完成: {sw.ElapsedMilliseconds}ms", typeName);
1120: 
1121:         Project project;
1122:         if (_preWarmedWorkspace != null)
1123:         {
1124:             _workspace = _preWarmedWorkspace;
1125:             _preWarmedWorkspace = null;
1126:             PluginLogger.Info("[补全] 复用预热 Workspace", typeName);
1127:         }
1128:         else
1129:         {
1130:             _workspace = new ScriptWorkspace(host);
1131:             PluginLogger.Info("[补全] ScriptWorkspace 实例已创建", typeName);
1132:         }
1133: 
1134:         sw.Restart();
1135:         var existingProject = _workspace.CurrentSolution.Projects.FirstOrDefault();
1136:         if (existingProject != null)
1137:         {
1138:             project = existingProject.WithCompilationOptions(
1139:                 new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary)
1140:                     .WithAllowUnsafe(true));
1141:             PluginLogger.Info($"[补全] 复用预热项目: {sw.ElapsedMilliseconds}ms", typeName);
1142:         }
1143:         else
1144:         {
1145:             var projectInfo = ProjectInfo.Create(ProjectId.CreateNewId(), VersionStamp.Create(), "ScriptCompletion", "ScriptCompletion", LanguageNames.CSharp);
1146:             var newSolution = _workspace.CurrentSolution.AddProject(projectInfo);
1147:             project = newSolution.GetProject(projectInfo.Id)!.WithCompilationOptions(
1148:                 new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary)
1149:                     .WithAllowUnsafe(true));
1150:             PluginLogger.Info($"[补全] 项目创建完成: {sw.ElapsedMilliseconds}ms", typeName);
1151:         }
1152: 
1153:         // 扫描引用：引用来源由调用方（工具层）注入，合并 host 引用 + ScriptRefs 目录引用
1154:         sw.Restart();
1155:         var refs = _getReferences().ToList();
1156:         var seenRefs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
1157:         var refCount = 0;
1158:         foreach (var mdRef in refs)
1159:         {
1160:             if (mdRef is PortableExecutableReference per && per.FilePath != null)
1161:             {
1162:                 string key;
1163:                 try { key = System.IO.Path.GetFullPath(per.FilePath); }
1164:                 catch { key = per.FilePath; }
1165:                 if (!seenRefs.Add(key)) continue;
1166:             }
1167:             project = project.AddMetadataReference(mdRef);
1168:             refCount++;
1169:         }
1170:         PluginLogger.Info($"[补全] 已添加 {refCount} 个 MetadataReference: {sw.ElapsedMilliseconds}ms", typeName);
1171: 
1172:         sw.Restart();
1173:         // 用 SetCurrentSolution 直接替换（对齐 RoslynPad SetSubmissionDocument），
1174:         // 接受 AddProject + AddMetadataReference 全部变化，避免 TryApplyChanges 钩子链异常。
1175:         _workspace.SetCurrentSolution(project.Solution);
1176:         PluginLogger.Info($"[补全] SetCurrentSolution(项目+引用): {sw.ElapsedMilliseconds}ms", typeName);
1177: 
1178:         sw.Restart();
1179: 
1180:         // 添加两个文档：字段声明 partial class + 用户完整 partial class。
1181:         var genDocId = DocumentId.CreateNewId(project.Id);
1182:         var userDocId = DocumentId.CreateNewId(project.Id);
1183: 
1184:         var solution = project.Solution
1185:             .AddDocument(DocumentInfo.Create(genDocId, "ScriptGenerated.cs", folders: null,
1186:                 sourceCodeKind: SourceCodeKind.Regular))
