1205:         PluginLogger.Info($"[补全] 文档添加完成: genDocId={_documentId}, userDocId={_userDocumentId}: {sw.ElapsedMilliseconds}ms", typeName);
1206: 
1207:         _workspaceInitialized = true;
1208: 
1209:         var refsCount = _workspace.CurrentSolution.Projects.First().MetadataReferences.Count;
